static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}static wsound89_i16 nz(wsoundparticles89_context*c){c->state=c->state*1664525U+1013904223U;return(wsound89_i16)((c->state>>16)&65535U);}
wsound89_result wsoundparticles89_init(wsoundparticles89_context*c,wsound89_u32 seed){if(!c)return WSOUND89_EINVAL;c->state=seed?seed:0x50415254U;c->accum=0;c->env=c->impulse=c->low=c->res1=c->res2=0;c->density_q15=c->energy_q15=0;c->active=0;c->material=WSOUNDPARTICLES89_METAL;return WSOUND89_OK;}
wsound89_result wsoundparticles89_trigger(wsoundparticles89_context*c,wsoundparticles89_material m,wsound89_u16 d,wsound89_u16 e){if(!c||(wsound89_u32)m>4U)return WSOUND89_EINVAL;c->material=m;c->density_q15=d;c->energy_q15=e;c->env=32767;c->active=1;c->accum=0;return WSOUND89_OK;}
wsound89_i16 wsoundparticles89_process_sample(wsoundparticles89_context*c){wsound89_i32 n,mix;if(!c||!c->active)return 0;c->accum+=(wsound89_u32)c->density_q15;if(c->accum>=32768U){c->accum-=32768U;n=nz(c);c->impulse=((wsound89_i32)n*c->energy_q15)>>15;}else c->impulse=(c->impulse*19000)>>15;n=nz(c);c->low+=(n-c->low)>>4;c->res1+=(c->impulse-c->res1)>>2;c->res2+=(c->res1-c->res2)>>3;mix=c->impulse;if(c->material==WSOUNDPARTICLES89_METAL)mix+=(c->res1>>1)-(c->res2>>2);else if(c->material==WSOUNDPARTICLES89_GLASS)mix+=(c->res1-c->res2);else if(c->material==WSOUNDPARTICLES89_GRAVEL)mix=(mix>>1)+(c->low>>2);else if(c->material==WSOUNDPARTICLES89_WOOD)mix=(mix>>1)+(c->res2>>1);else mix=(mix>>2)+(c->low>>4);mix=(mix*c->env)>>15;c->env-=(c->env>>9)+4;c->density_q15=(wsound89_u16)(((wsound89_u32)c->density_q15*32720U)>>15);if(c->env<20||c->density_q15<5){c->active=0;c->env=0;}return sat(mix);}
